function filterProducts(){
  if(!activeCategory)return;
  const query=searchInput.value.trim().normalize("NFKD").toLowerCase();
  let visible=0;
  grid.querySelectorAll(".product-card").forEach(card=>{
    const matches=(card.dataset.search || card.textContent || "").normalize("NFKD").toLowerCase().includes(query);
    card.hidden=!matches;
    if(matches)visible++;
  });
  searchResults.textContent=query?`${visible} product${visible===1?"":"s"} found`:`${visible} product${visible===1?"":"s"}`;
}
