// A short synthesized UI click sound; browsers unlock audio on the first user click.
let uiAudioContext = null;
function playUiClick(){
  try{
    uiAudioContext ||= new (window.AudioContext||window.webkitAudioContext)();
    if(uiAudioContext.state==="suspended")uiAudioContext.resume();
    const oscillator=uiAudioContext.createOscillator();
    const gain=uiAudioContext.createGain();
    const now=uiAudioContext.currentTime;
    oscillator.type="sine";
    oscillator.frequency.setValueAtTime(720,now);
    oscillator.frequency.exponentialRampToValueAtTime(420,now+.045);
    gain.gain.setValueAtTime(.035,now);
    gain.gain.exponentialRampToValueAtTime(.001,now+.055);
    oscillator.connect(gain);gain.connect(uiAudioContext.destination);
    oscillator.start(now);oscillator.stop(now+.06);
  }catch(_){/* Audio is optional when the browser does not support Web Audio. */}
}
document.addEventListener("click",event=>{
  if(event.target.closest("button,[role='button'],.download-button"))playUiClick();
},true);

// Mobile browsers shrink the visual viewport when the payment form keyboard opens.
// Keep the fixed modal backdrop sized and positioned to that visible area.
// Mobile modal viewport sizing. Do not track visualViewport scroll: on iOS that
// event can fire while the page is being scrolled and make the modal follow it.
let pageScrollYBeforeModal = 0;
function syncModalViewport() {
  const vv = window.visualViewport;
  backdrop.style.setProperty("--modal-viewport-height", `${vv ? vv.height : window.innerHeight}px`);
  backdrop.style.setProperty("--modal-viewport-top", "0px");
}
if (window.visualViewport) {
  window.visualViewport.addEventListener("resize", syncModalViewport);
  window.addEventListener("orientationchange", syncModalViewport);
}
function lockPageScrollForModal() {
  pageScrollYBeforeModal = window.scrollY || window.pageYOffset || 0;
  document.body.style.position = "fixed";
  document.body.style.top = `-${pageScrollYBeforeModal}px`;
  document.body.style.left = "0";
  document.body.style.right = "0";
  document.body.style.width = "100%";
  document.body.style.overflow = "hidden";
}
function unlockPageScrollForModal() {
  document.body.style.position = "";
  document.body.style.top = "";
  document.body.style.left = "";
  document.body.style.right = "";
  document.body.style.width = "";
  document.body.style.overflow = "";
  window.scrollTo(0, pageScrollYBeforeModal);
}

function setFeedback(message, isError) {
  formFeedback.textContent = message;
  formFeedback.classList.toggle("error", !!isError);
}
