// ---- Screenshot handling -------------------------------------------------
// Shrinks very large screenshots so they fit Discord's upload limit.
async function prepareImage(file) {
  if (file.size <= MAX_UPLOAD_BYTES) return file;
  let bitmap;
  try { bitmap = await createImageBitmap(file); }
  catch (_) { throw new Error("This image is too large and could not be compressed. Please choose a smaller screenshot."); }
  const maxSide = 2000;
  const scale = Math.min(1, maxSide / Math.max(bitmap.width, bitmap.height));
  const canvas = document.createElement("canvas");
  canvas.width = Math.round(bitmap.width * scale);
  canvas.height = Math.round(bitmap.height * scale);
  canvas.getContext("2d").drawImage(bitmap, 0, 0, canvas.width, canvas.height);
  for (let q = 0.85; q >= 0.4; q -= 0.15) {
    const blob = await new Promise(res => canvas.toBlob(res, "image/jpeg", q));
    if (blob && blob.size <= MAX_UPLOAD_BYTES) {
      return new File([blob], "screenshot.jpg", {type:"image/jpeg"});
    }
  }
  throw new Error("Image is still too large. Please choose a smaller screenshot.");
}
function safeFileName(file) {
  const map = {"image/png":"png","image/jpeg":"jpg","image/webp":"webp","image/gif":"gif"};
  const ext = map[file.type] || "png";
  return `payment-screenshot-${Date.now()}.${ext}`;
}

// ---- Submit order to Discord (details + screenshot as a real file upload) --
orderForm.addEventListener("submit", async e=>{
  e.preventDefault();
  const submitBtn = orderForm.querySelector(".submit-order");
  const fileInput = document.getElementById("screenshot");
  let file = fileInput.files[0];
  if (!selectedProduct) return;
  if (!file) { setFeedback("Please attach your payment screenshot.", true); return; }
  if (!file.type.startsWith("image/")) { setFeedback("Please choose an image file.", true); return; }

  const details = {
    ...selectedProduct,
    paymentMethod: chosenMethod,
    transactionLast4: document.getElementById("last4").value.trim(),
    discordUsername: document.getElementById("discord").value.trim(),
    message: document.getElementById("orderMessage").value.trim()
  };
  const original = submitBtn.innerHTML;
  submitBtn.disabled = true;
  submitBtn.textContent = "SENDING...";
  setFeedback("Sending your order, please wait...", false);

  try {
    file = await prepareImage(file);
    const name = safeFileName(file);
    const content =
`🛒 NEW ORDER

📦 Product: ${details.product}
📅 Duration: ${details.duration}
💰 Price: ৳${details.price}
💳 Payment: ${details.paymentMethod}
🔢 Last 4 Digit: ${details.transactionLast4}
👤 Discord: ${details.discordUsername}
${details.message ? `💬 Message: ${details.message}\n` : ""}📸 Screenshot attached below`;

    const body = new FormData();
    body.append("payload_json", JSON.stringify({
      content,
      allowed_mentions: {parse: []},          // stops @everyone / @role pings from user input
      attachments: [{id: 0, filename: name}]
    }));
    body.append("files[0]", file, name);       // the actual screenshot

    const res = await fetch(DISCORD_WEBHOOK_URL + "?wait=true", {method:"POST", body});
    if (!res.ok) throw new Error(`Discord returned an error (${res.status}). Please try again.`);

    orderForm.reset();
    setFeedback("✓ Order sent! The store owner will review your payment and contact you on Discord.", false);
  } catch (err) {
    const offline = err instanceof TypeError;
    setFeedback(offline ? "Network error. Check your connection and try again." : (err.message || "Something went wrong. Please try again."), true);
  } finally {
    submitBtn.disabled = false;
    submitBtn.innerHTML = original;
  }
});

// ---- Copy payment number --------------------------------------------------
const pc=document.getElementById("particleCanvas"),ctx=pc.getContext("2d");let dots=[];function resize(){const d=Math.min(devicePixelRatio||1,2);pc.width=innerWidth*d;pc.height=innerHeight*d;pc.style.width=innerWidth+"px";pc.style.height=innerHeight+"px";ctx.setTransform(d,0,0,d,0,0);dots=Array.from({length:Math.min(65,Math.floor(innerWidth/20))},()=>({x:Math.random()*innerWidth,y:Math.random()*innerHeight,r:Math.random()*1.5+.5,v:Math.random()*.35+.08,a:Math.random()*.4+.12}));}function animate(){ctx.clearRect(0,0,innerWidth,innerHeight);for(const p of dots){p.y-=p.v;if(p.y< -4){p.y=innerHeight+4;p.x=Math.random()*innerWidth;}ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle=`rgba(255,35,58,${p.a})`;ctx.shadowColor="#ff233a";ctx.shadowBlur=8;ctx.fill();}requestAnimationFrame(animate);}resize();animate();window.addEventListener("resize",resize);
copyBtn.addEventListener("click", async function () {
  const number = (PAYMENT_NUMBERS[chosenMethod] || "").trim();
  if (!number) { copyFeedback.textContent = "Payment details are not available yet."; return; }
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(number);
    } else {
      const input = document.createElement("textarea");
      input.value = number;
      input.style.position = "fixed";
      input.style.left = "-9999px";
      document.body.appendChild(input);
      input.select();
      const ok = document.execCommand("copy");
      input.remove();
      if (!ok) throw new Error("Copy failed");
    }
    copyBtn.textContent = "COPIED ✓";
    copyFeedback.textContent = "Number copied: " + number;
  } catch (_) {
    copyFeedback.textContent = "Copy failed. Please select and copy the number manually.";
  }
  clearTimeout(copyTimer);
  copyTimer = setTimeout(resetCopyUI, 2500);
});
